namespace FScript.Runtime

open System
open System.Collections.Generic
open System.Reflection
open FScript.Extensibility

/// Mutable storage shared by all aliases of the same cell. Access is not synchronized.
[<Sealed>]
type Ref<'t> internal (initialValue: 't) =
    member val internal Value = initialValue with get, set

/// Typed CLR entry points for code generated by FScript.
[<AbstractClass; Sealed>]
type CompiledRef private () =
    static member Create(value: 't) = Ref<'t>(value)
    static member Get(cell: Ref<'t>) = cell.Value
    static member Set(value: 't, cell: Ref<'t>) = cell.Value <- value

    static member FScriptCompiledTypes () : IEnumerable<KeyValuePair<string, Type>> =
        [ KeyValuePair("Ref", typedefof<Ref<_>>) ]

    static member FScriptCompiledFunctions () : IEnumerable<KeyValuePair<string, MethodInfo>> =
        [ KeyValuePair("Ref.create", typeof<CompiledRef>.GetMethod("Create"))
          KeyValuePair("Ref.get", typeof<CompiledRef>.GetMethod("Get"))
          KeyValuePair("Ref.set", typeof<CompiledRef>.GetMethod("Set")) ]

module RefProvider =
    let private descriptor =
        { Name = "Ref"; HostManaged = true; Fields = Map.empty; TypeParameters = [0] }

    let private types = { HostInterop.empty with Types = [descriptor] }
    let private item = TVar 0
    let private handle = TApplied(descriptor.Name, [item])

    let private operation name args result impl =
        { Name = "Ref." + name; Arity = List.length args
          Scheme = Forall([0], List.foldBack (fun arg rest -> TFun(arg, rest)) args result)
          Impl = impl }

    let private cell value =
        match (HostInterop.unwrap descriptor.Name value).Payload with
        | :? Ref<ScriptValue> as cell -> cell
        | _ -> raise (ExtensionException("Expected a reference handle."))

    let register () : ExtensionRegistration =
        let functions =
            [ operation "create" [item] handle (fun _ -> function
                | [value] -> HostInterop.create types descriptor.Name Map.empty (CompiledRef.Create value)
                | _ -> raise (ExtensionException("Ref.create expects a value.")))
              operation "get" [handle] item (fun _ -> function
                | [handle] -> CompiledRef.Get(cell handle)
                | _ -> raise (ExtensionException("Ref.get expects a reference.")))
              operation "set" [item; handle] TUnit (fun _ -> function
                | [value; handle] ->
                    CompiledRef.Set(value, cell handle)
                    VUnit
                | _ -> raise (ExtensionException("Ref.set expects a value and a reference."))) ]
        { types with Functions = functions }
